{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "Welcome to the Lobby",
          "intent": "Introduce the protagonist's death and the absurdity of the System's arrival lounge.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist reaches the tutorial kiosk and receives his initial stat allocation."
        },
        {
          "section_id": 2,
          "title": "The Glitch in the Machine",
          "intent": "Establish the 'Luck' stat exploit through experimentation on tutorial dummies.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "Protagonist successfully triggers a guaranteed 'Miss-Crit' on a practice dummy."
        },
        {
          "section_id": 3,
          "title": "Tutorial Boss Logic",
          "intent": "Demonstrate the build's viability in a low-stakes boss encounter.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The tutorial boss is defeated via the 'Miss-Crit' exploit, granting passage to the world."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Post-Game Analysis",
          "intent": "Analyze the tutorial loot and identify the need for specialized movement gear.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist identifies the 'Running Shoes of the Coward' in a local shop's inventory."
        },
        {
          "section_id": 2,
          "title": "The Scavenger's Grind",
          "intent": "Acquire enough currency through minor exploits to afford the gear.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "Protagonist purchases the 'Running Shoes of the Coward' from a sketchy vendor."
        },
        {
          "section_id": 3,
          "title": "Calibration Run",
          "intent": "Test the new movement speed in conjunction with the luck exploit.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Protagonist successfully kites a pack of field mobs without taking a hit."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Wildwood Infiltration",
          "intent": "Navigate the initial layers of the Wildwood Dungeon solo.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist reaches the entrance to the Wildwood boss arena."
        },
        {
          "section_id": 2,
          "title": "The Kiting Masterclass",
          "intent": "Engage the boss by using the environment and superior speed to avoid direct combat.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The boss is lured into a sequence of its own environmental traps."
        },
        {
          "section_id": 3,
          "title": "Flagged for Review",
          "intent": "Complete the dungeon and trigger the System's automated exploit detection.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The boss dies and a System Notification warns of an 'Exploit Flag' on the protagonist's account."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Committee's Gavel",
          "intent": "Show the immediate consequences of being flagged by the Balance Committee.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist is cornered by Balance Committee enforcers in a neutral zone."
        },
        {
          "section_id": 2,
          "title": "Breaking the Geometry",
          "intent": "Escape the enforcers by exploiting a clipping glitch in the city walls.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "Protagonist successfully glitches through the environment to evade capture."
        },
        {
          "section_id": 3,
          "title": "Slumming It",
          "intent": "Find temporary safety in the city's lawless district.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Protagonist reaches a safehouse in the slums, officially becoming a fugitive."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Unstoppable Object",
          "intent": "Locate a potential ally who can survive the protagonist's chaotic playstyle.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist finds Barnaby, the disgraced tank, in a dive bar."
        },
        {
          "section_id": 2,
          "title": "The Sales Pitch",
          "intent": "Convince Barnaby that an 'illegal' build is his only path back to relevance.",
          "section_role": "rising_action",
          "target_scene_count": 3,
          "end_condition": "Barnaby agrees to a trial run and joins the protagonist's party."
        },
        {
          "section_id": 3,
          "title": "Field Test",
          "intent": "Develop a tactical synergy between high-speed kiting and 'Unstoppable' tanking.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The duo clears a high-level patrol, confirming their synergy is viable."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Breaching the Perimeter",
          "intent": "Infiltrate the outer defenses of the Spire of Math.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist and Barnaby bypass the Spire's logic-gates and enter the main tower."
        },
        {
          "section_id": 2,
          "title": "The Vertical Climb",
          "intent": "Fight through the tower's automated defense systems using physics exploits.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The party reaches the central processing core at the top of the Spire."
        },
        {
          "section_id": 3,
          "title": "Deleting the Evidence",
          "intent": "Access the System terminal to remove the 'Exploit' flag before deletion occurs.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The 'Exploit' flag is successfully converted into a 'Unique Title' just as the deletion timer hits zero."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Guardian's Glitch",
          "intent": "Defeat the Spire's final guardian using the newly acquired Unique Title.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Spire Guardian is defeated, dropping the legendary 'Dev-Tool'."
        },
        {
          "section_id": 2,
          "title": "Structural Failure",
          "intent": "Escape the collapsing Spire as the System attempts to rectify the logic error.",
          "section_role": "falling_action",
          "target_scene_count": 3,
          "end_condition": "Protagonist and Barnaby exit the tower as it de-rezzes into raw data."
        },
        {
          "section_id": 3,
          "title": "Into the Frontier",
          "intent": "Set out for the frontier zones where the System's rules are less rigid.",
          "section_role": "resolution",
          "target_scene_count": 3,
          "end_condition": "The protagonist crosses the border into the frontier, ready to break more rules."
        }
      ]
    }
  ]
}

